Reet, tha wants t'count pairs o' nodes i' a tree wi' distance exactly k. Best way t'do it's wi' centroid decomposition — runs quick an' fits tha limits.

How it works (short an' sweet):
- Find a centroid o' t'tree (a node so none o' t'components after removin' it's bigger than half t'nodes).
- For each subtree o' that centroid, gather distances o' nodes frae t'centroid (only keep distances ≤ k).
- Use a frequency array cnt[0..k] where cnt[d] says how many nodes we already seen at distance d frae t'centroid. Start wi' cnt[0]=1 (t'centroid itself).
- For a subtree, fer each node at distance d buy in that subtree, add cnt[k-d] to answer (pairs makin' distance k passin' through t'centroid).
- After countin' contributions frae that subtree, add its distances inta cnt so subsequent subtrees can pair wi' it.
- Then remove t'centroid an' recurse on each subtree (centroid decomposition).

Complexity: O(n log n) in practice, with extra factor up to k when buildin' arrays (k ≤ 500) — well within limits.

Here's a tidy C++ implementation tha can use. Compile wi' a modern compiler.

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int n, K;
vector<vector<int>> g;
vector<int> sz;
vector<char> removed;
ll ans = 0;

void dfs_size(int u, int p) {
    sz[u] = 1;
    for (int v : g[u]) if (v != p && !removed[v]) {
        dfs_size(v, u);
        sz[u] += sz[v];
    }
}

int find_centroid(int u, int p, int total) {
    for (int v : g[u]) if (v != p && !removed[v]) {
        if (sz[v] > total/2) return find_centroid(v, u, total);
    }
    return u;
}

void collect_dists(int u, int p, int depth, vector<int> &out) {
    if (depth > K) return;
    out.push_back(depth);
    for (int v : g[u]) if (v != p && !removed[v]) collect_dists(v, u, depth+1, out);
}

void decompose(int entry) {
    dfs_size(entry, -1);
    int c = find_centroid(entry, -1, sz[entry]);
    removed[c] = 1;

    vector<int> cnt(K+1, 0);
    cnt[0] = 1; // centroid itself

    for (int v : g[c]) if (!removed[v]) {
        vector<int> dists;
        collect_dists(v, c, 1, dists);
        // count pairs between nodes in this subtree and nodes from previously processed subtrees (incl centroid)
        for (int d : dists) if (d <= K) ans += cnt[K - d];
        // add these distances to cnt
        for (int d : dists) if (d <= K) cnt[d]++;
    }

    // recurse on components
    for (int v : g[c]) if (!removed[v]) decompose(v);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n >> K)) return 0;
    g.assign(n+1, {});
    for (int i = 0; i < n-1; ++i) {
        int a, b; cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    sz.assign(n+1, 0);
    removed.assign(n+1, 0);

    decompose(1);
    cout << ans << '\n';
    return 0;
}

